import{_ as s,o as n,c as t,ah as r}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Conseiller admissions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/equipe/conseiller.md","filePath":"src/guide/equipe/conseiller.md"}'),a={name:"guide/equipe/conseiller.md"};function i(o,e,l,d,u,c){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="conseiller-admissions" tabindex="-1">Conseiller admissions <a class="header-anchor" href="#conseiller-admissions" aria-label="Permalink to &quot;Conseiller admissions&quot;">​</a></h1><p>Le Conseiller admissions instruit les candidatures : il mène l&#39;entretien, veille au test et rend la décision. Le rôle est attribué par l&#39;Administrateur. Votre travail se fait dans <strong>Parcours → Candidatures</strong>.</p><h2 id="la-file-des-candidatures" tabindex="-1">La file des candidatures <a class="header-anchor" href="#la-file-des-candidatures" aria-label="Permalink to &quot;La file des candidatures&quot;">​</a></h2><p>Les candidatures arrivent dans une <strong>file partagée</strong>. Trois filtres aident à s&#39;y retrouver : <strong>Tout le monde</strong>, <strong>Non prises en charge</strong>, <strong>Les miennes</strong>. On peut aussi chercher par nom ou par e-mail, et filtrer par programme et par statut (en cours, admises, refusées).</p><p>Chaque ligne indique l&#39;étape en cours (dépôt, entretien, test, décision), son échéance, le conseiller en charge, et les repères <strong>Mineur</strong> et <strong>En retard</strong>.</p><h2 id="prendre-un-dossier-en-charge" tabindex="-1">Prendre un dossier en charge <a class="header-anchor" href="#prendre-un-dossier-en-charge" aria-label="Permalink to &quot;Prendre un dossier en charge&quot;">​</a></h2><p>Ouvrez la candidature et cliquez sur <strong>Prendre en charge</strong> : vous en devenez le <strong>conseiller responsable</strong>. Un dossier ne se prend qu&#39;une fois. Seul le conseiller responsable peut clore l&#39;entretien et rendre la décision. Le Coordinateur pédagogique ne prend pas de dossier, mais peut le <strong>réattribuer</strong> à un autre conseiller, qui reçoit alors les rappels.</p><p>La fiche rassemble tout : le candidat, le format demandé, sa motivation, ses pièces jointes (que vous pouvez télécharger), les étapes avec leur date, et l&#39;historique de ses <strong>candidatures précédentes</strong>. Un candidat <strong>mineur</strong> est signalé : son inscription demandera la signature d&#39;un représentant légal.</p><h2 id="l-entretien" tabindex="-1">L&#39;entretien <a class="header-anchor" href="#l-entretien" aria-label="Permalink to &quot;L&#39;entretien&quot;">​</a></h2><p>Menez l&#39;entretien <strong>dans les 5 jours ouvrés</strong> après le dépôt (du lundi au vendredi, hors jours fériés saisis par l&#39;Administrateur). Puis cliquez sur <strong>Saisir l&#39;entretien</strong>, rédigez le <strong>compte rendu</strong>, qui reste interne, et <strong>Clôturer l&#39;entretien</strong>.</p><p>La clôture <strong>ouvre le test</strong> : le candidat reçoit le lien par e-mail, à condition que la banque de questions du programme soit validée. Sinon, le test attend ; vous cliquez sur <strong>Envoyer le lien du test</strong> une fois la banque validée.</p><h2 id="le-test" tabindex="-1">Le test <a class="header-anchor" href="#le-test" aria-label="Permalink to &quot;Le test&quot;">​</a></h2><p>Le candidat passe le test sans compte, avec un lien à usage unique, valable 48 heures. Il a 2 tentatives de 45 minutes, sur 10 questions. Son score lui est montré dès l&#39;envoi. La fiche vous donne, pour chaque lien, ses tentatives, leur état (en cours, non soumise) et le score sur 10.</p><p>Le seuil de 6 sur 10 est <strong>indicatif</strong> : le dossier passe en décision <strong>quel que soit le score</strong>. Une tentative réussie clôt le test.</p><p>Si le lien <strong>expire</strong>, ou si les tentatives sont épuisées faute de temps, vous êtes relancé une fois. Rien n&#39;est automatique : à vous de choisir.</p><ul><li><strong>Envoyer un nouveau lien</strong> remet les tentatives à zéro (le nombre de renvois est conservé) ;</li><li><strong>Clôturer le test</strong> fait passer le dossier en décision.</li></ul><h2 id="la-decision" tabindex="-1">La décision <a class="header-anchor" href="#la-decision" aria-label="Permalink to &quot;La décision&quot;">​</a></h2><p>Rendez la décision <strong>dans les 3 jours ouvrés</strong> qui suivent le test : <strong>Rendre la décision</strong>, puis choisissez <strong>Admis</strong> ou <strong>Refusé</strong> et saisissez le <strong>motif</strong>, obligatoire. Le motif reste interne ; le candidat est prévenu par e-mail et reçoit sa lettre de décision.</p><ul><li><strong>Admis.</strong> Choisissez la <strong>cohorte</strong> du candidat. La liste ne propose que les cohortes pas encore démarrées, avec des places et le format du candidat. Si aucune ne convient, laissez « Sans cohorte » : le Coordinateur affectera l&#39;apprenant plus tard. Le compte devient Apprenant et son inscription est créée.</li><li><strong>Refusé.</strong> Le dossier est clos, sans paiement ni accès à Sève. Le candidat ne peut pas redéposer pendant 7 jours.</li></ul><h2 id="les-rappels" tabindex="-1">Les rappels <a class="header-anchor" href="#les-rappels" aria-label="Permalink to &quot;Les rappels&quot;">​</a></h2><p>Une tâche quotidienne vous relance, une seule fois par étape, quand une échéance est dépassée : entretien non mené, test non passé, décision non rendue. Le rappel va au conseiller responsable, ou à <strong>tous les conseillers</strong> tant que personne n&#39;a pris le dossier. Il part par e-mail, et sur Sève et WhatsApp si votre compte et votre téléphone le permettent.</p>',21)])])}const h=s(a,[["render",i]]);export{g as __pageData,h as default};
